TEST(SilkCore, MatchesReference) {
    for (const CoreCase& test : kCases) {
        player::audio::silk::SilkCoreState state;
        const int fs = test.fs_khz;
        state.nb_subfr = test.nb_subfr;
        state.subfr_length = 5 * fs;
        state.frame_length = state.nb_subfr * state.subfr_length;
        state.ltp_mem_length = 20 * fs;
        state.lpc_order = fs == 16 ? 16 : 10;
        state.signal_type = test.signal_type;
        state.quant_offset_type = test.quant_offset;
        state.seed = test.seed;
        state.nlsf_interp_coef_q2 = test.interp;
        state.loss_count = test.loss_cnt;
        state.prev_signal_type = test.prev_signal_type;
        state.prev_gain_q16 = test.prev_gain;
        state.lag_prev = test.lag_prev;
        state.out_buf.assign(test.out_buf, test.out_buf + state.ltp_mem_length + 2 * state.subfr_length);
        for (int i = 0; i < 16; ++i) state.s_lpc_q14_buf[i] = test.s_lpc_buf[i];
        player::audio::silk::SilkDecoderControl control;
        for (int i = 0; i < 4; ++i) control.gains_q16[i] = test.gains[i];
        for (int h = 0; h < 2; ++h) {
            for (int i = 0; i < 16; ++i) control.pred_coef_q12[h][i] = test.pred[h][i];
        }
        for (int i = 0; i < 20; ++i) control.ltp_coef_q14[i] = test.ltp[i];
        for (int i = 0; i < 4; ++i) control.pitch_l[i] = test.pitch[i];
        control.ltp_scale_q14 = test.ltp_scale;
        std::vector<int16_t> xq(state.frame_length, 0);
        player::audio::silk::decodeCore(state, control, xq.data(), test.pulses);
        for (int i = 0; i < state.frame_length; ++i) {
            EXPECT_EQ(xq[i], test.xq[i]) << "xq " << i;
        }
        for (int i = 0; i < state.frame_length; ++i) {
            EXPECT_EQ(state.exc_q14[i], test.exc[i]) << "exc " << i;
        }
        for (int i = 0; i < 16; ++i) {
            EXPECT_EQ(state.s_lpc_q14_buf[i], test.s_lpc_out[i]) << "slpc " << i;
        }
        EXPECT_EQ(state.prev_gain_q16, test.prev_gain_out);
    }
}

